pragma solidity >=0.8.0;

contract EventProbe {
    event CtorIndexed(address indexed who, bytes32 tag);
    event OneIndexed(uint indexed a, uint b);
    event TwoIndexed(address indexed a, uint indexed b, string c);
    event ThreeIndexed(address indexed a, bytes indexed data, uint indexed n);
    event Dup(uint indexed v);

    uint256 public count;

    constructor(address who) {
        emit CtorIndexed(who, bytes32(uint256(0xC0FFEE)));
        count = 1;
    }

    function emitMulti() public {
        emit OneIndexed(11, 22);
        emit TwoIndexed(msg.sender, 33, "hello-events");
        emit ThreeIndexed(msg.sender, hex"aabbccdd", 44);
        emit Dup(55);
        emit Dup(55);
        count += 5;
    }

    function emitSimple(uint256 v) public {
        emit OneIndexed(v, v + 1);
        count += 1;
    }

    function getCount() public view returns (uint256) {
        return count;
    }
}
